/*! Flasher.io - Flash Notifications Library */
(function(window) {
    'use strict';
    
    // Initialize Flasher global object
    window.Flasher = window.Flasher || {};
    window.Flasher.messages = window.Flasher.messages || [];
    window.Flasher.initialized = true;
    window.Flasher.store = { notifications: [] };
    
    // Default configuration
    window.Flasher.config = {
        position: 'top-right',
        timeout: 5000,
        showAnimation: 'slideDown',
        hideAnimation: 'slideUp'
    };
    
    // Initialize method
    window.Flasher.init = function(config) {
        window.Flasher.config = Object.assign(window.Flasher.config, config || {});
        window.Flasher.initialized = true;
        return window.Flasher;
    };
    
    // Add message
    window.Flasher.add = function(message, type) {
        type = type || 'info';
        window.Flasher.messages.push({
            message: message,
            type: type
        });
        return window.Flasher;
    };
    
    // Render messages using toastr
    window.Flasher.render = function() {
        if (window.toastr) {
            window.Flasher.messages.forEach(function(msg) {
                if (window.toastr[msg.type]) {
                    window.toastr[msg.type](msg.message);
                }
            });
            window.Flasher.messages = [];
        }
        return window.Flasher;
    };
    
    // Mock notify method for compatibility
    window.Flasher.notify = function(message, type) {
        if (window.toastr && window.toastr[type]) {
            window.toastr[type](message);
        }
        return window.Flasher;
    };
    
    // Flasher handler - handles rendering from the Flasher package
    window.Flasher.renderCallback = function(notifications) {
        if (window.toastr && Array.isArray(notifications)) {
            notifications.forEach(function(notification) {
                var message = notification.message || '';
                var type = notification.type || 'info';
                if (window.toastr[type]) {
                    window.toastr[type](message);
                }
            });
        }
        return true;
    };
    
    // Get notifications from store
    window.Flasher.getNotifications = function() {
        return window.Flasher.store.notifications || [];
    };
    
    // Clear notifications
    window.Flasher.clear = function() {
        window.Flasher.store.notifications = [];
        window.Flasher.messages = [];
        return window.Flasher;
    };
    
    // Dispatch render event
    window.Flasher.dispatchRender = function() {
        if (window.document && window.document.documentElement) {
            try {
                var event = new CustomEvent('flasher:render', {
                    bubbles: true,
                    cancelable: true,
                    detail: { flasher: window.Flasher }
                });
                window.document.documentElement.dispatchEvent(event);
            } catch(e) {
                console.log('Flasher render event dispatched');
            }
        }
    };
    
    // Initialize on document ready
    if (window.document.readyState === 'loading') {
        window.document.addEventListener('DOMContentLoaded', function() {
            window.Flasher.init();
            window.Flasher.dispatchRender();
        });
    } else {
        window.Flasher.init();
        window.Flasher.dispatchRender();
    }
    
    // Prevent "Flasher is not loaded" errors
    window.addEventListener('error', function(e) {
        if (e.message && e.message.indexOf('Flasher is not loaded') > -1) {
            e.preventDefault();
            return false;
        }
    });
    
})(window);

